import styled from '@emotion/styled';
import { theme } from 'theme';

export const StyledNoDataYet = styled.span({
  width: '100%',
  display: 'flex',
  flexDirection: 'column',
  gap: theme.spacing['2'],
  justifyContent: 'center',
  alignItems: 'center',
});

export const StyledFlag = styled.img({
  width: '48px !important',
  height: '48px !important',
  minWidth: '48px !important',
  minHeight: '48px !important',
  div: {
    '&:hover': {
      background: 'none',
    },
  },
});

type StyledVariationColor = 'red' | 'green';

interface StyledVariationProps {
  $color?: StyledVariationColor;
}

export const StyledVariation = styled('div', {
  shouldForwardProp: (propName) => propName !== '$color',
})<StyledVariationProps>(({ $color }) => ({
  display: 'flex',
  justifyContent: 'center',
  gap: '0.375rem',
  fontSize: '12px',
  ...($color === 'red' && {
    color: theme.colors.charts.txt.status.decrease,
  }),
  ...($color === 'green' && {
    color: theme.colors.charts.txt.status.increase,
  }),
}));

export const StyledBlackTooltipContainer = styled.div({
  background: '#141414',
  color: '#ffffff',
  padding: '0 8px',
  borderRadius: theme.borderRadius['2'],
  fontSize: theme.fonts.fontSizes['1'],
  fontFamily: theme.fonts.paragraph,
  fontWeight: 'normal',
  display: 'flex',
  alignItems: 'center',
  justifyContent: 'center',
  position: 'relative',
  minHeight: '32px',

  '&::before': {
    content: '""',
    position: 'absolute',
    top: '-8px',
    left: '50%',
    transform: 'translateX(-50%)',
    width: '0',
    height: '0',
    borderLeft: '8px solid transparent',
    borderRight: '8px solid transparent',
    borderBottom: '8px solid #141414',
  },
});
